head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf31204";
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "if_O_INITDATE", fn: function(){ return (!(String(((dma_Cal13.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal13.O_INITDATE"); })())) == null ? '' : ((dma_Cal13.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal13.O_INITDATE"); })()))).length === 0)); } }, { id: "tr_104", fn: function(){ return (!(String(((dma_Cal13.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal13.O_INITDATE"); })())) == null ? '' : ((dma_Cal13.get("O_INITDATE") ?? (() => { throw new Error("unresolved:" + "Cal13.O_INITDATE"); })()))).length === 0)); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb0", fn: function () { return "ㆍ기산일(이사회결의 전일) : " + String(dma_Cal13.get("O_INITDATE")); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { /* TODO Stage2: [sdd] 행 복사 대상 부재:  it.childId */ continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", COM_NM);
};

// [A] 초기 목록 미해결 — jldstf31204: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { /* TODO Stage2: [sdd] 전환 파라미터 수신 대상 없음: dma_pageContext — 읽는 자리 0 */ };

scwin.form_frmISU_CD = { action: "", method: 'post', target: '' };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31204' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31204' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_rowCopy();
        scwin.init_conds();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldstf31204.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_70_onclick
 * @description img_70 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onclick = function(e){
    try {
        IsurcdSearch2('ISU_CD','COM_NM',315,155)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31204.img_70_onclick' }); }
};

/**
 * @method
 * @name img_70_onmouseover
 * @description img_70 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_70_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31204.img_70_onmouseover' }); }
};

/**
 * @method
 * @name btn_Cal13_onclick
 * @description btn_Cal13 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Cal13_onclick = async function(e){
    try {
        await scwin.cal13()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31204.btn_Cal13_onclick' }); }
};

/**
 * @method
 * @name btn_ExcelDown_onclick
 * @description btn_ExcelDown 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_ExcelDown_onclick = async function(e){
    try {
        await scwin.excelDown('excelData13')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31204.btn_ExcelDown_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Cal13
 * @description Cal13 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Cal13 = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal13"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Cal13", unresolved: "action:self_submit:tx_fn_Cal13" };
};

/**
 * @method
 * @name tx_fn_ExcelDown
 * @description Excel Down 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_ExcelDown = async function () {
    try { return await $c.data.downFile("/bizspt/excelDown.jsp", "", ($c.util.getComponent("dma_ExcelDownReq") ? $c.util.getComponent("dma_ExcelDownReq").getJSON() : {})); } catch (_e) { await $c.exception.handleError(_e, { context: '다운로드' }); return null; }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name cal13
 * @description cal13 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.cal13 = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('cal_decisionDateForStockOption').getValue() == null ? '' : String($c.util.getComponent('cal_decisionDateForStockOption').getValue())) === '') {
        await $c.win.alert("[이사회 결의일 or 주총결의일]을 입력하세요.");
        $c.util.getComponent("cal_decisionDateForStockOption").focus();
        return;
    }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    $c.util.getComponent("dma_basicInfo").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_basicInfo").set("COM_NM", encodeURI($c.util.getComponent('ipt_COM_NM').getValue()));
    $c.util.getComponent('dma_Cal13Req').set('method', "processCalculateRelatedDisclosure13");
    await scwin.tx_fn_Cal13();
};

/**
 * @method
 * @name excelDown
 * @description excel Down 처리
 * @param {String} tableID tableID
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.excelDown = async function (tableID) {
    if (tableID.rows.length === 0) {
        await $c.win.alert("[계산하기]을 실행 후 다운로드 할 수 있습니다.");
        return;
    }
    $c.util.getComponent('dma_Cal13Req').set('excelData', tableID.outerHTML);
    scwin.form_frmISU_CD.method = "post";
    scwin.form_frmISU_CD.target = "_blank";
    scwin.form_frmISU_CD.action = "/bizspt/excelDown.jsp";
    await scwin.tx_fn_ExcelDown();
};
